function normalizeHistogramTitleToYmd(v) {
  const s = String(v || '').trim();
  if (!s) return null;
  const iso = s.match(/\b(\d{4}-\d{2}-\d{2})\b/);
  if (iso) return iso[1];
  const us = s.match(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/);
  if (us) {
    const mm = String(us[1]).padStart(2, '0');
    const dd = String(us[2]).padStart(2, '0');
    const yyyy = String(us[3]);
    return `${yyyy}-${mm}-${dd}`;
  }
  const monMap = {
    jan: 1,
    january: 1,
    feb: 2,
    february: 2,
    mar: 3,
    march: 3,
    apr: 4,
    april: 4,
    may: 5,
    jun: 6,
    june: 6,
    jul: 7,
    july: 7,
    aug: 8,
    august: 8,
    sep: 9,
    sept: 9,
    september: 9,
    oct: 10,
    october: 10,
    nov: 11,
    november: 11,
    dec: 12,
    december: 12,
  };
  const monFirst = s.match(/\b([A-Za-z]{3,9})\s+(\d{1,2})(?:st|nd|rd|th)?\s*,?\s*(\d{4})\b/);
  if (monFirst) {
    const mon = String(monFirst[1] || '').trim().toLowerCase();
    const mNum = monMap[mon] || null;
    const dNum = parseInt(String(monFirst[2] || ''), 10);
    const yNum = parseInt(String(monFirst[3] || ''), 10);
    if (mNum && yNum && dNum) return `${String(yNum).padStart(4, '0')}-${String(mNum).padStart(2, '0')}-${String(dNum).padStart(2, '0')}`;
  }
  const dayFirst = s.match(/\b(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]{3,9})\s*,?\s*(\d{4})\b/);
  if (dayFirst) {
    const dNum = parseInt(String(dayFirst[1] || ''), 10);
    const mon = String(dayFirst[2] || '').trim().toLowerCase();
    const mNum = monMap[mon] || null;
    const yNum = parseInt(String(dayFirst[3] || ''), 10);
    if (mNum && yNum && dNum) return `${String(yNum).padStart(4, '0')}-${String(mNum).padStart(2, '0')}-${String(dNum).padStart(2, '0')}`;
  }
  return null;
}

