function parseNumLoose(v, keyHint) {
  const seen = new Set();
  const scaleByKey = (n, kHint) => {
    if (n == null || !Number.isFinite(Number(n))) return null;
    const k = kHint ? String(kHint) : '';
    if (!k) return Number(n);
    if (/micros?/i.test(k)) return Number(n) / 1_000_000;
    if (/millicents?/i.test(k) || /milli\s*cents?/i.test(k)) return Number(n) / 100_000;
    if (/cents?/i.test(k) && !/percent|pct|rate/i.test(k)) return Number(n) / 100;
    return Number(n);
  };

  const parseAny = (x, depth, kHint) => {
    if (x == null) return null;
    if (typeof x === 'number') {
      if (!Number.isFinite(x)) return null;
      return scaleByKey(x, kHint);
    }
    if (typeof x === 'string') {
      const s0 = String(x).trim();
      if (!s0) return null;
      const s1 = s0.replace(/[%,$\s]/g, '').replace(/,/g, '');
      const n1 = Number(s1);
      if (Number.isFinite(n1)) return scaleByKey(n1, kHint);
      const s2 = s0.replace(/[^0-9.\-]/g, '');
      const n2 = Number(s2);
      if (!Number.isFinite(n2)) return null;
      return scaleByKey(n2, kHint);
    }
    if (typeof x !== 'object') return null;
    if (seen.has(x)) return null;
    seen.add(x);
    if (depth > 3) return null;

    if (Array.isArray(x)) {
      for (const it of x) {
        const n = parseAny(it, depth + 1, kHint);
        if (n != null) return n;
      }
      return null;
    }

    const candidates = ['amount', 'value', 'raw', 'val', 'metricValue', 'formattedValue', 'displayValue', 'number'];
    for (const k of candidates) {
      if (Object.prototype.hasOwnProperty.call(x, k)) {
        const n = parseAny(x[k], depth + 1, k);
        if (n != null) return n;
      }
    }

    for (const [kk, vv] of Object.entries(x)) {
      const n = parseAny(vv, depth + 1, kk);
      if (n != null) return n;
    }
    return null;
  };

  return parseAny(v, 0, keyHint);
}

